   var axis=(hand.position-lower.position).normalized;var normal=Vector3.ProjectOnPlane(Device.up,axis);var face=Vector3.ProjectOnPlane(root.forward*.35f+Vector3.up*.8f-root.right*.3f,axis);lower.rotation=Quaternion.AngleAxis(Vector3.SignedAngle(normal,face,axis)*a,axis)*lower.rotation;var target=Device.position+Vector3.up*.08f;var desired=root.TransformPoint(new Vector3(-.20f,1.66f,.28f));motor.view.transform.position=Vector3.Lerp(motor.view.transform.position,desired,a);motor.view.transform.rotation=Quaternion.Slerp(motor.view.transform.rotation,Quaternion.LookRotation(target-motor.view.transform.position),a);
